// Renders assets/data/stats.json, generated by tools/build_stats.py.
//
// Two things this file is deliberately careful about:
//
// 1. Sorting compares typed numbers from value(), never the rendered string.
//    The previous comparator stripped non-digits, so an en-dash in one cell
//    made the PLAYOFFS column sort by 581,819,212,425.
// 2. Career totals and per-season rates are never labelled "total" and
//    "average" side by side. Career PF mostly ranks by how long someone has
//    played; the per-season figure is the comparable one, and they order
//    differently. The grouping, the ordering and the emphasis keep them apart.
//
// Long-form content (playoff years, ring lore) lives in an expandable detail
// row rather than inline: as inline text the RING column alone was 411px,
// 23% of the whole table and wider than a phone.

const STATS_PATH = "/assets/data/stats.json";

// group  — spanning label in the first header row
// short  — label in the second header row
// more   — hidden in compact mode, restored by the ALL STATS toggle
const COLUMNS = [
  {
    key: "name", group: "", short: "TEAM", cls: "col-team",
    value: (m) => m.name,
    text: (m) => m.name,
  },
  {
    key: "record", group: "CAREER", short: "W-L", cls: "col-record",
    value: (m) => m.total.wins - m.total.losses,
    text: (m) => `${m.total.wins}-${m.total.losses}`,
  },
  {
    key: "pct", group: "CAREER", short: "PCT", cls: "col-percent",
    value: (m) => m.total.pct,
    text: (m) => `${(m.total.pct * 100).toFixed(1)}%`,
  },
  {
    key: "playoffs", group: "PLAYOFFS", short: "MADE", cls: "col-playoffs",
    value: (m) => m.playoffs.made / Math.max(m.playoffs.possible, 1),
    text: (m) => `${m.playoffs.made}/${m.playoffs.possible}`,
  },
  {
    key: "ring", group: "PLAYOFFS", short: "RINGS", cls: "col-ring",
    value: (m) => m.rings.length,
    text: (m) =>
      m.rings.length
        ? "💍".repeat(m.rings.length) +
          (m.rings.some((r) => r.mickeyMouse) ? "*" : "")
        : "",
  },
  {
    key: "playoffRecord", group: "PLAYOFFS", short: "W-L",
    cls: "col-playoff-record",
    value: (m) => m.playoffs.record.wins - m.playoffs.record.losses,
    text: (m) => `${m.playoffs.record.wins}-${m.playoffs.record.losses}`,
  },
  {
    key: "avgPf", group: "PTS / SEASON", short: "PF", cls: "col-pts",
    value: (m) => m.points.pf / m.seasons,
    text: (m) => (m.points.pf / m.seasons).toFixed(0),
  },
  {
    key: "avgPa", group: "PTS / SEASON", short: "PA", cls: "col-pts",
    value: (m) => m.points.pa / m.seasons,
    text: (m) => (m.points.pa / m.seasons).toFixed(0),
  },
  {
    key: "espnW", group: "ESPN", short: "W", cls: "col-win-espn", more: true,
    value: (m) => m.espn.wins,
    text: (m) => String(m.espn.wins),
  },
  {
    key: "espnL", group: "ESPN", short: "L", cls: "col-loss-espn", more: true,
    value: (m) => m.espn.losses,
    text: (m) => String(m.espn.losses),
  },
  {
    key: "sleeperW", group: "SLEEPER", short: "W", cls: "col-win-sleeper",
    more: true,
    value: (m) => m.sleeper.wins,
    text: (m) => String(m.sleeper.wins),
  },
  {
    key: "sleeperL", group: "SLEEPER", short: "L", cls: "col-loss-sleeper",
    more: true,
    value: (m) => m.sleeper.losses,
    text: (m) => String(m.sleeper.losses),
  },
  {
    key: "totalW", group: "TOTAL", short: "W", cls: "col-total-wins",
    more: true,
    value: (m) => m.total.wins,
    text: (m) => String(m.total.wins),
  },
  {
    key: "totalL", group: "TOTAL", short: "L", cls: "col-total-losses",
    more: true,
    value: (m) => m.total.losses,
    text: (m) => String(m.total.losses),
  },
  {
    key: "seasons", group: "CAREER PTS", short: "SZNS", cls: "col-career-pts",
    more: true,
    value: (m) => m.seasons,
    text: (m) => String(m.seasons),
  },
  {
    key: "totalPf", group: "CAREER PTS", short: "PF", cls: "col-career-pts",
    more: true,
    value: (m) => m.points.pf,
    text: (m) => m.points.pf.toFixed(0),
  },
  {
    key: "totalPa", group: "CAREER PTS", short: "PA", cls: "col-career-pts",
    more: true,
    value: (m) => m.points.pa,
    text: (m) => m.points.pa.toFixed(0),
  },
];

let MANAGERS = [];
let SORT = { key: null, direction: null };
let SEARCH_TERM = "";
let COMPACT = false;
const EXPANDED = new Set();

// Playoff years and ring lore, shown in the expandable row. Kept out of the
// grid so one column of prose cannot dictate the width of the whole table.
function detailText(manager) {
  const parts = [];
  if (manager.playoffs.years.length) {
    parts.push(
      "Playoffs: " +
        manager.playoffs.years.map((y) => `'${String(y).slice(2)}`).join(", ")
    );
  }
  manager.rings.forEach((ring) => {
    const year = ring.mickeyMouse ? `${ring.year}*` : String(ring.year);
    parts.push(ring.note ? `Ring ${year} — ${ring.note}` : `Ring ${year}`);
  });
  if (!parts.length) parts.push("No playoff appearances.");
  return parts.join(" · ");
}

function tbody() {
  return document.querySelector("#stats-table tbody");
}

function activeColumns() {
  return COMPACT ? COLUMNS.filter((c) => !c.more) : COLUMNS;
}

function setMessage(text) {
  const body = tbody();
  if (!body) return;
  body.innerHTML = "";
  const tr = document.createElement("tr");
  const td = document.createElement("td");
  td.colSpan = COLUMNS.length;
  td.className = "stats-message";
  td.textContent = text;
  tr.appendChild(td);
  body.appendChild(tr);
}

// Two header rows: spanning groups, then the sortable leaf columns. Only the
// leaf row is clickable, so the sort model is unchanged.
function buildHeader() {
  const thead = document.querySelector("#stats-table thead");
  if (!thead) return;
  thead.innerHTML = "";

  const groupRow = document.createElement("tr");
  groupRow.className = "stats-group-row";
  const leafRow = document.createElement("tr");
  leafRow.id = "stats-header-row";

  const cols = activeColumns();
  let index = 0;
  while (index < cols.length) {
    const group = cols[index].group;
    let span = 1;
    while (index + span < cols.length && cols[index + span].group === group) {
      span += 1;
    }
    const th = document.createElement("th");
    if (!group) {
      // TEAM has no group; let it own both rows so it stays sticky.
      th.rowSpan = 2;
      th.textContent = cols[index].short;
      th.dataset.key = cols[index].key;
      th.classList.add("sortable");
      if (cols[index].cls) th.classList.add(cols[index].cls);
      if (SORT.key === cols[index].key && SORT.direction) {
        th.classList.add(SORT.direction === "asc" ? "sort-asc" : "sort-desc");
      }
    } else {
      th.colSpan = span;
      th.textContent = group;
      th.classList.add("stats-group");
      if (cols.slice(index, index + span).every((c) => c.more)) {
        th.classList.add("col-more");
      }
    }
    groupRow.appendChild(th);

    if (group) {
      cols.slice(index, index + span).forEach((col) => {
        const leaf = document.createElement("th");
        leaf.textContent = col.short;
        leaf.dataset.key = col.key;
        leaf.classList.add("sortable");
        if (col.cls) leaf.classList.add(col.cls);
        if (col.more) leaf.classList.add("col-more");
        if (SORT.key === col.key && SORT.direction) {
          leaf.classList.add(SORT.direction === "asc" ? "sort-asc" : "sort-desc");
        }
        leafRow.appendChild(leaf);
      });
    }
    index += span;
  }

  thead.appendChild(groupRow);
  thead.appendChild(leafRow);
}

function visibleRows() {
  let rows = MANAGERS.slice();

  if (SEARCH_TERM) {
    rows = rows.filter(
      (m) =>
        COLUMNS.some((c) => c.text(m).toLowerCase().includes(SEARCH_TERM)) ||
        detailText(m).toLowerCase().includes(SEARCH_TERM)
    );
  }

  if (SORT.key && SORT.direction) {
    const col = COLUMNS.find((c) => c.key === SORT.key);
    const sign = SORT.direction === "asc" ? 1 : -1;
    rows.sort((a, b) => {
      const va = col.value(a);
      const vb = col.value(b);
      if (typeof va === "number" && typeof vb === "number") {
        return (va - vb) * sign;
      }
      return String(va).localeCompare(String(vb)) * sign;
    });
  }

  return rows;
}

// Always rebuilt from data, so clearing a search cannot leave a stale order
// under a header still showing its sort arrow.
function render() {
  const body = tbody();
  const countLabel = document.getElementById("stats-count-label");
  if (!body) return;

  buildHeader();
  const rows = visibleRows();
  const cols = activeColumns();
  body.innerHTML = "";

  rows.forEach((m) => {
    const tr = document.createElement("tr");
    tr.className = "stats-row";
    tr.tabIndex = 0;
    tr.setAttribute("role", "button");
    tr.setAttribute("aria-expanded", EXPANDED.has(m.name) ? "true" : "false");
    tr.dataset.name = m.name;

    cols.forEach((col) => {
      const td = document.createElement("td");
      td.textContent = col.text(m);
      if (col.cls) td.classList.add(col.cls);
      if (col.more) td.classList.add("col-more");
      if (col.key === "pct" && m.total.pct > 0.5) td.classList.add("pct-good");
      tr.appendChild(td);
    });
    body.appendChild(tr);

    if (EXPANDED.has(m.name)) {
      const detail = document.createElement("tr");
      detail.className = "stats-detail";
      const cell = document.createElement("td");
      cell.colSpan = cols.length;
      // Sticky inner box so the text stays readable while the table is
      // scrolled sideways.
      const inner = document.createElement("div");
      inner.className = "stats-detail-inner";
      inner.textContent = detailText(m);
      cell.appendChild(inner);
      detail.appendChild(cell);
      body.appendChild(detail);
    }
  });

  if (countLabel) countLabel.textContent = String(rows.length);
  updateScrollAffordance();
}

function toggleRow(name) {
  if (EXPANDED.has(name)) EXPANDED.delete(name);
  else EXPANDED.add(name);
  render();
}

function setupSorting() {
  const thead = document.querySelector("#stats-table thead");
  if (!thead) return;
  thead.addEventListener("click", (evt) => {
    const th = evt.target.closest("th.sortable");
    if (!th) return;
    const key = th.dataset.key;
    if (SORT.key !== key) {
      SORT = { key, direction: "asc" };
    } else if (SORT.direction === "asc") {
      SORT = { key, direction: "desc" };
    } else {
      SORT = { key: null, direction: null };
    }
    render();
  });
}

function setupRowExpansion() {
  const body = tbody();
  if (!body) return;
  body.addEventListener("click", (evt) => {
    const row = evt.target.closest("tr.stats-row");
    if (row) toggleRow(row.dataset.name);
  });
  body.addEventListener("keydown", (evt) => {
    if (evt.key !== "Enter" && evt.key !== " ") return;
    const row = evt.target.closest("tr.stats-row");
    if (!row) return;
    evt.preventDefault();
    toggleRow(row.dataset.name);
  });
}

function setupSearch() {
  const input = document.getElementById("stats-search-input");
  if (!input) return;
  input.addEventListener("input", () => {
    SEARCH_TERM = input.value.trim().toLowerCase();
    render();
  });
}

function setupColumnToggle() {
  const button = document.getElementById("stats-cols-toggle");
  if (!button) return;
  // Labelled with the CURRENT state, not the action: a button reading
  // "ALL STATS" while showing the core set, styled as though active, is
  // ambiguous about which of the two it means.
  const sync = () => {
    button.textContent = COMPACT ? "COLUMNS: CORE" : "COLUMNS: ALL";
    button.setAttribute("aria-pressed", COMPACT ? "false" : "true");
    button.setAttribute(
      "title",
      COMPACT ? "Show every column" : "Show the core columns only"
    );
  };
  button.addEventListener("click", () => {
    COMPACT = !COMPACT;
    sync();
    render();
  });
  sync();
}

// Fades signal there is more table off-screen; they disappear at the extremes.
function updateScrollAffordance() {
  const pane = document.querySelector(".table-responsive");
  if (!pane) return;
  const max = pane.scrollWidth - pane.clientWidth;
  pane.classList.toggle("at-start", pane.scrollLeft <= 1);
  pane.classList.toggle("at-end", max <= 1 || pane.scrollLeft >= max - 1);
}

async function initStats() {
  COMPACT = window.matchMedia("(max-width: 640px)").matches;
  buildHeader();
  const pane = document.querySelector(".table-responsive");
  if (pane) pane.addEventListener("scroll", updateScrollAffordance);
  window.addEventListener("resize", updateScrollAffordance);

  try {
    const resp = await fetch(STATS_PATH);
    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    const doc = await resp.json();
    MANAGERS = doc.managers;
    setupSorting();
    setupRowExpansion();
    setupSearch();
    setupColumnToggle();
    render();
  } catch (err) {
    // Never leave a blank table with no explanation.
    setMessage(`Couldn't load the stats (${err.message}).`);
  }
}

document.addEventListener("DOMContentLoaded", initStats);
